package integration_test

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// validationCases is generated by tools/gencases from the botocore model.
// Regenerate it when awscli2 is updated or an operation is added.
type validationCases struct {
	APIVersion  string `json:"api_version"`
	JSONVersion string `json:"json_version"`
	Target      string `json:"target_prefix"`
	Cases       []struct {
		Name      string         `json:"name"`
		Operation string         `json:"operation"`
		Body      map[string]any `json:"body"`
		Expect    string         `json:"expect"`
	} `json:"cases"`
}

// TestCognitoIntegration_InputValidation sends requests that break one input constraint
// from the AWS model and checks that kumolo rejects them with the AWS error type.
// Requests are sent without the SDK because it validates required members client-side.
//
// Cases listed in testdata/cognito_validation_gaps.txt are known gaps and are skipped.
// A listed case that starts passing fails the test, so the list only shrinks.
func TestCognitoIntegration_InputValidation(t *testing.T) {
	raw, err := os.ReadFile("testdata/cognito_validation.json")
	require.NoError(t, err)
	var vc validationCases
	require.NoError(t, json.Unmarshal(raw, &vc))
	gaps := readGaps(t)

	clients := newTestClients(t)

	seen := map[string]bool{}
	for _, c := range vc.Cases {
		seen[c.Name] = true
		t.Run(c.Name, func(t *testing.T) {
			body, err := json.Marshal(c.Body)
			require.NoError(t, err)
			req, err := http.NewRequest(http.MethodPost, clients.baseURL+"/", bytes.NewReader(body))
			require.NoError(t, err)
			req.Header.Set("Content-Type", "application/x-amz-json-"+vc.JSONVersion)
			req.Header.Set("X-Amz-Target", vc.Target+"."+c.Operation)

			resp, err := http.DefaultClient.Do(req)
			require.NoError(t, err)
			defer func() { _ = resp.Body.Close() }()

			var got struct {
				Type    string `json:"__type"`
				Message string `json:"message"`
			}
			respBody, err := io.ReadAll(resp.Body)
			require.NoError(t, err)
			decodeErr := json.Unmarshal(respBody, &got)

			problem := ""
			switch {
			case decodeErr != nil:
				problem = fmt.Sprintf("response is not JSON: %d %q", resp.StatusCode, respBody)
			case c.Expect == "" && resp.StatusCode >= http.StatusInternalServerError,
				c.Expect == "" && resp.StatusCode >= http.StatusMultipleChoices && got.Type == "":
				problem = fmt.Sprintf(
					"base request did not reach the handler: %d %q",
					resp.StatusCode,
					respBody,
				)
			case c.Expect == "" && got.Type == "InvalidParameterException":
				// The base request must get past validation, otherwise the other cases
				// for this operation could pass for the wrong reason.
				problem = "base request rejected: " + got.Message
			case c.Expect != "" &&
				(resp.StatusCode != http.StatusBadRequest || got.Type != c.Expect):
				problem = fmt.Sprintf(
					"want 400 %s, got %d %s",
					c.Expect,
					resp.StatusCode,
					got.Type,
				)
			}

			if gaps[c.Name] {
				require.Lessf(
					t,
					resp.StatusCode,
					http.StatusInternalServerError,
					"known gap returned a server error: %q",
					respBody,
				)
				if problem == "" {
					require.FailNow(t, "passes now; remove it from cognito_validation_gaps.txt")
				}
				t.Skip("known gap: " + problem)
			}
			if problem != "" {
				require.FailNow(t, problem)
			}
		})
	}

	for name := range gaps {
		require.Truef(
			t,
			seen[name],
			"%q matches no generated case; remove it from the gaps list",
			name,
		)
	}
}

func readGaps(t *testing.T) map[string]bool {
	t.Helper()
	f, err := os.Open("testdata/cognito_validation_gaps.txt")
	require.NoError(t, err)
	defer func() { _ = f.Close() }()

	gaps := map[string]bool{}
	s := bufio.NewScanner(f)
	for s.Scan() {
		line := strings.TrimSpace(s.Text())
		if line != "" && !strings.HasPrefix(line, "#") {
			gaps[line] = true
		}
	}
	require.NoError(t, s.Err())
	return gaps
}

// TestCognitoIntegration_SerializationException sends bodies that cannot be read as the
// input shape. Responses verified against real AWS (issue #625).
func TestCognitoIntegration_SerializationException(t *testing.T) {
	clients := newTestClients(t)
	tests := []struct {
		name string
		op   string
		body string
		want string
	}{
		{"malformed JSON", "DescribeUserPool", `{`, `{"__type":"SerializationException"}`},
		{
			"number as string",
			"DescribeUserPool",
			`{"UserPoolId":123}`,
			`{"__type":"SerializationException","Message":"NUMBER_VALUE can not be converted to a String"}`,
		},
		{
			"string as integer",
			"ListUserPools",
			`{"MaxResults":"5"}`,
			`{"__type":"SerializationException","Message":"STRING_VALUE can not be converted to an Integer"}`,
		},
		{"scalar as list", "AdminUpdateUserAttributes",
			`{"UserPoolId":"us-east-1_a","Username":"u","UserAttributes":1}`,
			`{"__type":"SerializationException","Message":"Expected list or null"}`},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req, err := http.NewRequest(
				http.MethodPost, clients.baseURL+"/", strings.NewReader(tt.body),
			)
			require.NoError(t, err)
			req.Header.Set("Content-Type", "application/x-amz-json-1.1")
			req.Header.Set("X-Amz-Target", "AWSCognitoIdentityProviderService."+tt.op)

			resp, err := http.DefaultClient.Do(req)
			require.NoError(t, err)
			defer func() { _ = resp.Body.Close() }()
			got, err := io.ReadAll(resp.Body)
			require.NoError(t, err)

			require.Equal(t, http.StatusBadRequest, resp.StatusCode)
			require.JSONEq(t, tt.want, string(got))
		})
	}
}

// TestCognitoIntegration_NestedValidation sends requests that break a constraint inside a
// list, map or structure member. Messages verified against real AWS (issue #624).
func TestCognitoIntegration_NestedValidation(t *testing.T) {
	clients := newTestClients(t)
	tests := []struct {
		name string
		op   string
		body string
		want string
	}{
		{"list of structures", "AdminUpdateUserAttributes",
			`{"UserPoolId":"us-east-1_abc","Username":"u","UserAttributes":[{"Value":"y"}]}`,
			`1 validation error detected: Value null at 'userAttributes.1.member.name' ` +
				`failed to satisfy constraint: Member must not be null`},
		{"nested structure", "UpdateUserPool",
			`{"UserPoolId":"us-east-1_abc","Policies":{"PasswordPolicy":{}}}`,
			`1 validation error detected: Value '0' at 'policies.passwordPolicy.minimumLength' ` +
				`failed to satisfy constraint: Member must have value greater than or equal to 6`},
		{"missing UserPoolId", "AdminGetUser", `{"Username":""}`, `UserPoolId must not be null`},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req, err := http.NewRequest(
				http.MethodPost, clients.baseURL+"/", strings.NewReader(tt.body),
			)
			require.NoError(t, err)
			req.Header.Set("Content-Type", "application/x-amz-json-1.1")
			req.Header.Set("X-Amz-Target", "AWSCognitoIdentityProviderService."+tt.op)

			resp, err := http.DefaultClient.Do(req)
			require.NoError(t, err)
			defer func() { _ = resp.Body.Close() }()
			var got struct {
				Type    string `json:"__type"`
				Message string `json:"message"`
			}
			require.NoError(t, json.NewDecoder(resp.Body).Decode(&got))

			require.Equal(t, http.StatusBadRequest, resp.StatusCode)
			require.Equal(t, "InvalidParameterException", got.Type)
			require.Equal(t, tt.want, got.Message)
		})
	}
}
